generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName WHERE {
  {
    SELECT ?inv (SUM(xsd:decimal(?amt)) AS ?totalCash)
    WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amt .
    }
    GROUP BY ?inv
    HAVING (SUM(xsd:decimal(?amt)) < 10000)
  }

  ?inv a wm:Investor .
  OPTIONAL { ?inv wm:investorId ?investorId . }
  OPTIONAL { ?inv wm:investorName ?investorName . }

  FILTER EXISTS {
    ?inv wm:hasInvestmentGoal ?goal .
    ?goal wm:shortfall ?sf .
    FILTER(xsd:decimal(?sf) > 0)
  }

  FILTER EXISTS {
    ?inv wm:hasHolding ?hold .
    ?hold wm:returnsPct ?rp .
    FILTER(xsd:decimal(?rp) < 0)
  }

  ?inv wm:hasPortfolioHealth ?ph .
  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 65)
}

